// SigCap-CPU - resource cap enforcement demo
var CAP = { mechanism: "SigCap-CPU", limit: "200 ms/run", unit: "ms" };
var usage = 150, limitVal = 200;
console.log("Mechanism: " + CAP.mechanism);
console.log("Cap: " + limitVal + " " + CAP.unit + " (" + CAP.limit + ")");
console.log("Usage: " + usage + " " + CAP.unit);
console.log(usage > limitVal ? "RESULT: OVER LIMIT - policy engaged" : "RESULT: within budget - OK");

